/* Align mark, inlined as a data URI so the particle sampler can read its
   pixels without tripping the file:// canvas-taint rule. Regenerate with:
     python3 -c "import base64;print('window.ALIGN_MARK_DATAURL=\"data:image/png;base64,'+base64.b64encode(open('assets/align-mark.png','rb').read()).decode()+'\";')" > assets/mark-data.js
*/
window.ALIGN_MARK_DATAURL = "data:image/png;base64,";
